window.products.push({"id":578275,"name":"Kupilka Soup Bowl - Eco Dishware - Light & Durable","category":"homeandappliances","retail price":26.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51Rhxy2+2BL._AC_SL1260_.jpg","description":"KUPILKA products are made from Kareline Natural Fibre Composite material. The biomaterial consists of 50% pine fibre (wood) and 50% thermoplastic. All KUPILKA products are dishwasher safe. To ensure the longevity of the dishes, we do not recommend putting them in the microwave, stove or open fire. At the end of their life span, the products can be recycled, incinerated for heat energy or returned to the manufacturer for re-use. The Kupilka packaging is made from recycled cardboard.","images":["https://m.media-amazon.com/images/I/51Rhxy2+2BL._AC_SL1260_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kupilka","source_asin":"B07BN5318V","category_path":"Home & Kitchen"},"sku":"BM-578275","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07BN5318V","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07BN5318V","price_pending":true,"merchant_ready":false});
